#!/bin/bash
exec qemu-system-x86_64 -nodefaults -cpu qemu64,+rdrand,+rdtscp,+smap,+fsgsbase,+x2apic,+smep,+ssse3,+sse4.1,+sse4.2,+xsave,+xsaveopt,+avx,+avx2 -machine q35 -smp cores=2 -m 2G  -drive if=pflash,format=raw,readonly=on,file=/opt/homebrew/share/qemu/edk2-x86_64-code.fd -drive if=pflash,format=raw,file=<scratch>/boot/vars.fd  -device nec-usb-xhci,id=xhci -drive if=none,id=stick,format=raw,file=<scratch>/boot/stick.img -device usb-storage,bus=xhci.0,drive=stick,bootindex=0  -drive if=none,id=nvme0,format=raw,file=<scratch>/boot/nvme.img -device nvme,serial=deadbeef,drive=nvme0  -vga std -display none -serial file:<scratch>/boot/serial.log -no-reboot
